from pathlib import Path
from copy import deepcopy
import json, shutil, hashlib
from docx import Document
from docx.shared import Pt
from docx.oxml import OxmlElement
from docx.text.paragraph import Paragraph
from docx.table import Table

ROOT=Path('D:/00. Downloads/Apartamente Viena/00. Cladire 1 Schallergasse 35, 1120 Wien (Meidling)')
BASE=ROOT/'04. Firme + Executie/01. Verificator (Pruefingenieur)/TOMS'
OUT=BASE/'2026-10-01 Contract v3 - propunere'
OUT.mkdir(exist_ok=True)
WORK=OUT/'_lucru'; WORK.mkdir(exist_ok=True)
d=Document(next(BASE.glob('*v2.2).docx')))
ps=list(d.paragraphs); ts=list(d.tables)
def p(i,text):
    x=ps[i]
    for r in x.runs:r.text=''
    if x.runs:x.runs[0].text=text
    else:x.add_run(text)
def remove(x):
    e=x._element;e.getparent().remove(e)
def table(j,rows):
    t=ts[j]
    template=deepcopy(t.rows[1]._tr if len(t.rows)>1 else t.rows[0]._tr)
    while len(t.rows)>1:t._tbl.remove(t.rows[-1]._tr)
    for k,vals in enumerate(rows):
        if k:t._tbl.append(deepcopy(template))
        for c,v in zip(t.rows[k].cells,vals):c.text=str(v)
    for ri,r in enumerate(t.rows):
        for c in r.cells:
            for pp in c.paragraphs:
                pp.paragraph_format.space_after=Pt(4)
                for run in pp.runs:run.font.size=Pt(9);run.bold=(ri==0)
        pr=r._tr.get_or_add_trPr()
        no=OxmlElement('w:cantSplit');pr.append(no)
    return t

