for section in d.sections:
    for pp in section.footer.paragraphs:
        for run in pp.runs:
            run.text=run.text.replace('v2.2','v3').replace('22.09.2026','01.10.2026')
d.core_properties.title='Werkvertrag TOMS – Schallergasse 35 – Entwurf v3 – 01.10.2026'
d.core_properties.subject='Vertragsangebot; beiderseitige Unterzeichnung ausständig'
name='2026-10-01 Werkvertrag TOMS - Schallergasse 35 - Entwurf v3'
d.save(OUT/(name+'.docx'))
# Ordered text for EVA document generation, retaining all clauses and table cells.
blocks=[]
for e in d.element.body:
    if e.tag.endswith('}p'):
        pp=Paragraph(e,d);t=pp.text.strip()
        if t:
            if t.startswith(('§ ','Anlage ')) or t=='WERKVERTRAG':t='# '+t
            blocks.append(t)
    elif e.tag.endswith('}tbl'):
        tb=Table(e,d)
        if e is ts[5]._tbl:
            blocks.extend(['Für die Auftraggeberin: A&C Wohnart Immobilien GmbH', 'Cosmin Adrian Covaciu, Geschäftsführer', 'Ort / tatsächliches Unterschriftsdatum: ____________________', 'Unterschrift: __________________________________________', 'Für den Auftragnehmer: Toms Ziviltechniker GmbH', 'Dipl.-Ing. Ferdinand Toms', 'Ort / tatsächliches Unterschriftsdatum: ____________________', 'Unterschrift / Firmenstempel: ____________________________'])
            continue
        if e is ts[0]._tbl or e is ts[1]._tbl:
            blocks.extend(' | '.join(c.text.replace('\n','; ') for c in r.cells) for r in tb.rows)
            continue
        head=[c.text.replace('\n','; ') for c in tb.rows[0].cells]
        for r in tb.rows[1:]:
            blocks.append('- '+'; '.join((head[i]+': ' if head[i] else '')+c.text.replace('\n','; ') for i,c in enumerate(r.cells) if c.text.strip()))
        if len(tb.rows)==1:blocks.append(' | '.join(head))
content='\n\n'.join(blocks)
(WORK/'contract_content.txt').write_text(content,encoding='utf-8')
# Preserve original external annexes, offers and professional documents.
ann=OUT/'Beilagen';ann.mkdir(exist_ok=True)
for pattern in ['2026-09-23 Anlage 5*','2026-09-21 Anlage 5a*','2026-09-28 Fragekatalog*','ANG 839*','ANG 855*','2026-09-23 ANG 891*']:
    for f in BASE.glob(pattern):shutil.copy2(f,ann/f.name)
for f in (BASE/'Nachweise 2026.09.23').glob('*.pdf'):shutil.copy2(f,ann/f.name)
print(json.dumps({'output':str(OUT),'docx':name+'.docx','content_chars':len(content)},ensure_ascii=False))
